const DB_NAME = "menulens-offline";
const DB_VERSION = 1;
const SCANS_STORE = "scans";

function openDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result);

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(SCANS_STORE)) {
        const store = db.createObjectStore(SCANS_STORE, { keyPath: "id" });
        store.createIndex("created_at", "created_at", { unique: false });
      }
    };
  });
}

export async function cacheScanOffline(scan: {
  id: string;
  status: string;
  items_count: number;
  agent_summary?: string | null;
  enriched?: boolean;
  created_at: string;
  dishes?: { name: string; image_url: string }[];
  items?: {
    id: string;
    name: string;
    description?: string;
    price?: number;
    category?: string;
    image_url?: string;
    confidence?: number;
  }[];
}): Promise<void> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(SCANS_STORE, "readwrite");
    const store = transaction.objectStore(SCANS_STORE);
    const request = store.put(scan);

    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve();
  });
}

export async function getOfflineScans(): Promise<
  { id: string; status: string; items_count: number; agent_summary?: string | null; created_at: string; dishes?: { name: string; image_url: string }[] }[]
> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(SCANS_STORE, "readonly");
    const store = transaction.objectStore(SCANS_STORE);
    const request = store.getAll();

    request.onerror = () => reject(request.error);
    request.onsuccess = () => {
      const results = request.result as {
        id: string;
        status: string;
        items_count: number;
        agent_summary?: string | null;
        created_at: string;
        dishes?: { name: string; image_url: string }[];
      }[];
      results.sort(
        (a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
      );
      resolve(results);
    };
  });
}

export async function clearOfflineScans(): Promise<void> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(SCANS_STORE, "readwrite");
    const store = transaction.objectStore(SCANS_STORE);
    const request = store.clear();

    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve();
  });
}
